import assert from "node:assert/strict";
import fs from "node:fs";
import ts from "typescript";
import { evaluateAcquisitionGate } from "../lib/ai-acquisition/quality-gate.ts";
import { acquisitionIndustryMatchesVerifiedResult } from "../lib/ai-acquisition/industry-match.ts";
import { acquisitionIndustryMismatchReason } from "../lib/ai-acquisition/decision-reason.ts";
import { summarizeUsagePurposes } from "../lib/api-usage-purpose.ts";
import { discoveryCandidateLooksRelevant } from "../lib/ai-acquisition/relevance.ts";
import { googleProfileHasTemporalBusinessConflict } from "../lib/ai/google-profile-consistency.ts";

const base={automationStatus:"AUTO_DEVELOP",targetDecision:"VALID",score:82,identityStatus:"MATCHED",evidenceUrls:[{source_url:"https://example.com/services",evidence_strength:"STRONG"}],contacts:[{type:"EMAIL",value_normalized:"sales@example.com",verification_status:"NEW_VERIFIED",identity_match_status:"MATCHED",contact_status:"ACTIVE_UNKNOWN",exact_source_url:"https://example.com/contact"}]};
assert.equal(evaluateAcquisitionGate(base).accepted,true,"完整强证据和可追溯联系方式应允许入池");
assert.equal(evaluateAcquisitionGate({...base,targetDecision:"INVALID"}).accepted,false,"非目标不得入池");
assert.equal(evaluateAcquisitionGate({...base,identityStatus:"CONFLICTED"}).accepted,false,"主体冲突不得入池");
assert.equal(evaluateAcquisitionGate({...base,identityStatus:"AMBIGUOUS"}).accepted,false,"主体未确认不得自动入池");
assert.equal(evaluateAcquisitionGate({...base,evidenceUrls:[{source_url:"https://example.com",evidence_strength:"WEAK_HINT"}]}).accepted,false,"弱提示不能替代经营证据");
assert.equal(evaluateAcquisitionGate({...base,contacts:[{type:"PHONE",verification_status:"SOURCE_CONFIRMED",exact_source_url:null}]}).accepted,false,"联系方式无具体来源页面不得入池");
assert.equal(evaluateAcquisitionGate({...base,contacts:[{...base.contacts[0],identity_match_status:"AMBIGUOUS"}]}).accepted,false,"来源页与客户主体未匹配的联系方式不得入池");
assert.equal(evaluateAcquisitionGate({...base,contacts:[{...base.contacts[0],contact_status:"SHARED_CORPORATE"}]}).accepted,false,"集团共享联系方式不得当作具体门店的可触达联系方式");
assert.equal(evaluateAcquisitionGate({...base,contacts:[]}).verifiedTarget,true,"目标行业、主体和经营证据已核验时不得因缺联系方式否定目标属性");
assert.equal(evaluateAcquisitionGate({...base,contacts:[]}).accepted,false,"缺少可追溯联系方式的目标客户不得直接入池");
assert.equal(evaluateAcquisitionGate({...base,identityStatus:"AMBIGUOUS"}).evidenceComplete,false,"主体未匹配时不得把单一来源链接标为证据完整");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机维修店"],"手机维修店"),true,"核验行业与任务目标一致才可入池");
assert.match(acquisitionIndustryMismatchReason(["手机维修连锁店"],"手机维修店"),/缺少手机维修及多门店或连锁经营的直接证据/,
  "连锁店任务应解释业务与连锁双重证据门槛，而非笼统称行业不一致");
assert.match(acquisitionIndustryMismatchReason(["手机维修店"],"电脑维修店"),/缺少与本任务目标行业直接匹配的经营证据/,
  "其他目标行业仍应说明具体的行业证据不匹配");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机维修连锁店"],"手机维修店",["官网证明提供手机维修"]),false,"普通手机维修店不能仅凭行业标签进入连锁店任务");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机维修连锁店"],"Apple或MacBook维修店",["官网证明提供手机维修并有多门店或连锁经营"]),true,"主行业为Apple维修但有手机维修和连锁证据时不能误拒");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机维修连锁店"],"电脑维修店",["官网证明提供多门店或连锁经营"]),false,"仅有连锁证据而无手机维修证据不能入池");
assert.equal(discoveryCandidateLooksRelevant({companyName:"United Vape & Phone Repair Center",businessStatus:"OPERATIONAL",types:["food_store","service"],matchedTerms:["mobile device repair centres"]},["手机维修连锁店"],["mobile device repair centres"]),true,"明确标注手机维修的混合商家不得被无关Google分类提前排除，仍需补证");
assert.equal(discoveryCandidateLooksRelevant({companyName:"Mobile Tyres And Puncture Repairs",businessStatus:"OPERATIONAL",types:["car_repair","tire_shop"],matchedTerms:["mobile device repair centres"]},["手机维修连锁店"],["mobile device repair centres"]),false,"汽车流动维修不得因mobile一词混入手机维修核验");
assert.match(fs.readFileSync("workflows/ai-acquisition.ts","utf8"),/deepProcessed=Number\(screening\.data\.success_count\|\|0\)/,"技术失败候选不得提前计入已完成进度");
assert.match(fs.readFileSync("workflows/ai-acquisition.ts","utf8"),/state\.screening\.failed_count[\s\S]*ACQUISITION_SCREENING_ITEMS_FAILED/,"子任务技术失败应明确提示可重试，不能只在收尾完整性校验中报错");
assert.match(fs.readFileSync("workflows/ai-acquisition.ts","utf8"),/customer:customers!inner\(id\)[\s\S]*customer\.deleted_at[\s\S]*customer\.pool_status/,"自动去重不得把已删除或隔离中的客户当作现存重复客户");
assert.match(fs.readFileSync("app/api/ai-acquisition/candidates/[id]/review/route.ts","utf8"),/customer:customers!inner\(id\)[\s\S]*customer\.deleted_at[\s\S]*customer\.pool_status/,"人工复核入池也不得受已删除客户的历史联系方式阻挡");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机维修店"],"手机成品零售"),false,"成品手机零售不得混入维修店任务");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件批发商"],"手机外配件零售"),false,"普通外配件零售不得混入维修配件批发任务");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机维修店"],"手机外配件零售",["官网显示该商家销售手机壳和贴膜"]),false,"仅销售外配件不能借人工复核进入维修店任务");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机维修店"],"手机外配件零售",["官网服务页确认该商家提供iPhone屏幕更换维修"]),true,"外配件零售主分类下有同一主体手机换屏直接证据时不得误拒");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机维修店"],"手机外配件零售",["未发现该商家提供iPhone屏幕更换维修"]),false,"否定事实不得当作手机维修证据");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机维修店"],"手机外配件零售",["官网显示销售手机壳，同时提供笔记本电池更换维修"]),false,"电脑维修不能冒充手机维修业务");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件批发商"],"手机外配件零售",["官网向维修门店批发iPhone LCD屏幕总成和充电尾插"]),true,"有具体手机维修内配件批发证据的混合商家不能仅因主分类是外配件零售而误拒");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件零售商"],"维修内配件零售"),true,"配件零售任务必须识别已核验的维修内配件零售类别");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件零售商"],"手机外配件零售",["官网销售手机壳和充电器"]),false,"手机配件零售目标不能被外配件标签单独满足");
assert.match(acquisitionIndustryMismatchReason(["手机维修店"],"手机外配件零售"),/换屏／换电池/,"行业不匹配时应给出可核查的目标业务缺口");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件批发商"],"进口商或分销商",["Google商家页将该企业分类为汽车配件批发商"]),false,"汽车配件批发商不得借粗行业标签进入手机维修配件任务");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件批发商"],"进口商或分销商",["官网经营食品批发与餐饮供应"]),false,"食品批发商不得借wholesale泛词进入手机维修配件任务");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件批发商"],"进口商或分销商",["官网销售手机壳、耳机、充电器并提供批发账户"]),false,"只批发手机外配或成品不得冒充维修内配件分销商");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件批发商"],"进口商或分销商",["Google商家评论和官网服务页确认该企业提供手机换屏、换电池维修", "官网向trade accounts批发mobile accessories and batteries"]),true,"已核验维修企业同时经营相关配件或电池批发应认定为目标客户");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件批发商"],"进口商或分销商",["官网向trade accounts批发mobile accessories and batteries"]),false,"没有维修业务或维修内配件证据时普通外配电池批发不得自动入池");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件批发商"],"进口商或分销商",["企业官网显示向维修门店批发iPhone LCD屏幕总成、充电尾插和主板维修配件"]),true,"具有手机维修内配件及批发角色的直接证据应允许匹配");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["手机配件批发商"],"进口商或分销商",["官网主营手机和电脑维修内配件批发、分销及经销"]),true,"明确的手机电脑维修内配件贸易商即使自身不提供维修服务也应直接匹配");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["电脑配件批发商"],"进口商或分销商",["官网提供MacBook replacement screens, batteries and keyboards to trade accounts"]),true,"电脑维修配件及贸易账户证据应允许匹配");
assert.equal(acquisitionIndustryMatchesVerifiedResult(["电子设备维修服务商"],"其他维修行业"),true,"用户明确选择电子设备维修时应允许已核验的其他电子维修客户");
assert.match(fs.readFileSync("app/api/ai-acquisition/candidates/[id]/review/route.ts","utf8"),/acquisitionIndustryMatchesVerifiedResult[\s\S]*industry_type/,"人工复核重新入池也必须复用任务行业匹配门槛");
assert.match(fs.readFileSync("app/api/ai-acquisition/customers/route.ts","utf8"),/officialWebsiteUrl[\s\S]*historicalChannel[\s\S]*facebook_url/,"AI获客结果不得把历史Facebook地址继续显示为官网");
const acquisitionWorkflowSource=fs.readFileSync("workflows/ai-acquisition.ts","utf8");
assert.match(acquisitionWorkflowSource,/beginTask\(taskId: string, executionToken[\s\S]*eq\("last_dispatch_at", executionToken\)/,"过期工作流必须在启动阶段由派发令牌阻断");
assert.match(acquisitionWorkflowSource,/finishTask\([\s\S]*last_dispatch_at[\s\S]*executionToken[\s\S]*return false/,"过期工作流不得覆盖新一轮任务收尾状态");
for(const file of ["app/api/ai-acquisition/tasks/route.ts","app/api/ai-acquisition/tasks/[id]/route.ts","lib/ai-acquisition/dispatch.ts"]){assert.match(fs.readFileSync(file,"utf8"),/start\(aiAcquisitionWorkflow,\s*\[[^\]]*,\s*(?:executionToken|now)\]\)/,`${file} 派发获客工作流时必须携带执行令牌`);}
const relevanceBase={businessStatus:"OPERATIONAL",matchedTerms:["mobile phone repair shop"]};
assert.equal(discoveryCandidateLooksRelevant({...relevanceBase,companyName:"The Toughphone Ltd",types:["cell_phone_store"]},["手机维修店"],["mobile phone repair"]),false,"仅销售手机成品的商店不得进入维修客户付费补证");
assert.equal(discoveryCandidateLooksRelevant({...relevanceBase,companyName:"Computer Laptop Repair",types:["computer_repair_service"]},["电脑维修店"],["computer repair"]),true,"明确电脑维修业务不得被前置门槛漏掉");
assert.equal(discoveryCandidateLooksRelevant({...relevanceBase,companyName:"Trust Computers & Repairs",types:["electronics_store","service"]},["电脑维修店"],["computer repair shop"]),true,"电脑和维修的复数形式不得被完全匹配误杀");
assert.equal(discoveryCandidateLooksRelevant({...relevanceBase,companyName:"Birmingham Laptop Repairs",types:["electronics_store","service"]},["电脑维修店"],["computer repair shop"]),true,"电脑维修任务必须把laptop repair识别为同域候选并进入证据核验");
assert.equal(discoveryCandidateLooksRelevant({...relevanceBase,companyName:"PC Repair Guru",types:["service"]},["电脑维修店"],["computer repair shop"]),true,"电脑维修任务必须把PC repair识别为同域候选并进入证据核验");
assert.equal(discoveryCandidateLooksRelevant({...relevanceBase,companyName:"iRepairFone",types:["service"]},["手机维修店"],["mobile phone repair"]),true,"紧凑维修品牌名不得因Google泛类别而在补证前被误拒");
assert.equal(discoveryCandidateLooksRelevant({...relevanceBase,companyName:"360phonefix.co.uk",types:["establishment"]},["手机维修店"],["mobile phone repair"]),true,"包含phone fix的域名式商家名必须进入证据核验");
assert.equal(discoveryCandidateLooksRelevant({...relevanceBase,companyName:"fixmybrokenscreen.co.uk",types:["establishment"]},["手机维修店"],["mobile phone repair"]),true,"包含screen fix的紧凑商家名必须进入证据核验");
assert.equal(discoveryCandidateLooksRelevant({...relevanceBase,companyName:"City Barber",types:["hair_salon"]},["手机维修店"],["mobile phone repair"]),false,"精确维修查询不能让明确理发店绕过跨行业门槛");
assert.equal(discoveryCandidateLooksRelevant({businessStatus:"OPERATIONAL",companyName:"North Foods",types:["food_wholesaler"],matchedTerms:["food wholesaler"]},["食品批发商"],["food wholesaler"]),true,"跨行业的行业实词加批发角色必须继续支持，不能写死为电子行业");
assert.equal(discoveryCandidateLooksRelevant({businessStatus:"OPERATIONAL",companyName:"Harbour Hotel",types:["lodging"],matchedTerms:["hotel"]},["酒店"],["hotel"]),true,"明确行业名称匹配应支持服务业客户");
assert.equal(discoveryCandidateLooksRelevant({businessStatus:"OPERATIONAL",companyName:"Motor Parts Direct",types:["auto_parts_store"],matchedTerms:["spare parts"]},["手机配件批发商"],["mobile phone spare parts wholesaler"]),false,"汽车配件商不得因spare parts泛词进入手机配件核验");
assert.equal(discoveryCandidateLooksRelevant({businessStatus:"OPERATIONAL",companyName:"Environmental Computer Recycling and Removals Ltd",types:["recycling_center"],matchedTerms:["computer repair"]},["电脑维修店"],["computer repair shop"]),false,"电脑回收清运不得因computer词进入电脑维修核验");
assert.equal(discoveryCandidateLooksRelevant({businessStatus:"OPERATIONAL",companyName:"Fresh Produce Wholesale",types:["food_wholesaler"],matchedTerms:["wholesale"]},["食品饮料批发商"],["food wholesaler"]),true,"用户明确选择食品行业时必须允许食品批发候选");
assert.equal(googleProfileHasTemporalBusinessConflict({name:"ابو عبدالله للحلاقة",description:"Mobile Phone/Gadget Repairs & Sales. Alamo's repairs phones.",reviews:[],types:["hair_care"]}),true,"Google当前理发店名称与历史手机维修描述冲突时必须阻止自动认定主体和行业");
assert.equal(googleProfileHasTemporalBusinessConflict({name:"Alamo's Mobile Repairs",description:"Mobile Phone/Gadget Repairs & Sales",reviews:[],types:["mobile_phone_repair_shop"]}),false,"名称与经营内容一致的手机维修商家不得被误判为历史资料冲突");
assert.equal(googleProfileHasTemporalBusinessConflict({name:"Toon Repair and Vape Hub - Phone & Laptop Repair Newcastle",description:"We specialize in mobile phone repair, iPhone screen replacement and battery replacement",reviews:[],types:["vaporizer_store","mobile_phone_repair_shop"]}),false,"当前商家名称同时明确经营电子烟与手机维修时不得误判为换主体");
assert.equal(googleProfileHasTemporalBusinessConflict({name:"City Vape Hub",description:"Previous owner offered mobile phone repairs",reviews:[],types:["vaporizer_store"]}),true,"当前名称仅显示电子烟而历史描述显示手机维修时仍须隔离主体冲突");
const purposeSummary=summarizeUsagePurposes([
  {provider:"GOOGLE_PLACES",operation:"目标商家搜索",quantity:2,amount_usd:0.064},
  {provider:"GOOGLE_PLACES",operation:"商家详情与联系方式",quantity:1,amount_usd:0.02},
  {provider:"OPENAI",operation:"客户分析",quantity:1,input_tokens:900,output_tokens:100,amount_usd:0.002,metadata:{channel:"all_available_sources"}},
]);
assert.deepEqual(purposeSummary.find(row=>row.purpose==="目标商家发现"),{provider:"GOOGLE_PLACES",purpose:"目标商家发现",calls:2,tokens:0,cost_usd:0.064},"Google目标商家搜索必须单独归类");
assert.deepEqual(purposeSummary.find(row=>row.purpose==="商家详情与联系方式"),{provider:"GOOGLE_PLACES",purpose:"商家详情与联系方式",calls:1,tokens:0,cost_usd:0.02},"Google联系方式详情必须单独归类");
assert.deepEqual(purposeSummary.find(row=>row.provider==="OPENAI"),{provider:"OPENAI",purpose:"多来源证据综合与目标判断",calls:1,tokens:1000,cost_usd:0.002},"OpenAI综合分析必须按真实调用统计且不得重复计算Token");

const migration=fs.readFileSync(new URL("../supabase/migrations/202609150004_ai_acquisition_core.sql",import.meta.url),"utf8");
const multiIndustryMigration=fs.readFileSync(new URL("../supabase/migrations/202609150005_ai_acquisition_multi_industry.sql",import.meta.url),"utf8");
const checkpointMigration=fs.readFileSync(new URL("../supabase/migrations/202609150006_ai_acquisition_discovery_checkpoints.sql",import.meta.url),"utf8");
const keywordTraceMigration=fs.readFileSync(new URL("../supabase/migrations/202609160001_ai_acquisition_keyword_trace.sql",import.meta.url),"utf8");
const incrementalSearchMigration=fs.readFileSync(new URL("../supabase/migrations/202609160002_ai_acquisition_incremental_search.sql",import.meta.url),"utf8");
const coverageEfficiencyMigration=fs.readFileSync(new URL("../supabase/migrations/202609170001_ai_acquisition_coverage_efficiency.sql",import.meta.url),"utf8");
const acquisitionScaleMigration=fs.readFileSync(new URL("../supabase/migrations/202609170002_ai_acquisition_scale.sql",import.meta.url),"utf8");
const costIsolationMigration=fs.readFileSync(new URL("../supabase/migrations/202609180003_ai_acquisition_task_cost_isolation.sql",import.meta.url),"utf8");
const strictReviewQueueMigration=fs.readFileSync(new URL("../supabase/migrations/202609210001_strict_ai_acquisition_review_queue.sql",import.meta.url),"utf8");
assert.match(migration,/AI_STAGING/);
assert.match(migration,/claim_stalled_ai_acquisition_tasks/);
assert.match(migration,/revoke all on public\.ai_acquisition_tasks/);
assert.match(multiIndustryMigration,/industries text\[\]/);
assert.match(multiIndustryMigration,/get_ai_acquisition_usage_summary/);
assert.match(checkpointMigration,/ai_acquisition_discovery_checkpoints[\s\S]*next_page_token[\s\S]*results jsonb/,"发现阶段必须按检索表达和分页持久化续跑检查点");
assert.match(keywordTraceMigration,/matched_keywords text\[\][\s\S]*current_stage[\s\S]*acquisition_match_keywords text\[\]/,"必须持久化执行阶段、候选命中关键词和入池客户匹配关键词");
assert.match(incrementalSearchMigration,/ai_acquisition_search_scopes[\s\S]*claim_ai_acquisition_search_scope[\s\S]*ACTIVE_ELSEWHERE[\s\S]*RECENTLY_COMPLETED[\s\S]*complete_ai_acquisition_search_scope/,"跨任务必须按国家与实际检索表达串行执行并跳过近期已覆盖范围");
assert.match(incrementalSearchMigration,/ai_acquisition_discovery_checkpoints[\s\S]*'GOOGLE_TEXT_V1'\|\|chr\(10\)/,"上线时必须继承已有任务完成的检索范围，不能从头重复采集");
assert.match(incrementalSearchMigration,/grant execute on function public\.claim_ai_acquisition_search_scope[\s\S]*service_role/,"增量检索原子占用函数必须只授权服务端执行");
assert.match(coverageEfficiencyMigration,/target_count between 1 and 5000[\s\S]*REUSED_RECENT[\s\S]*REUSED_ACTIVE/,"数据库必须支持广域发现安全上限和可审计的缓存复用状态");
assert.match(acquisitionScaleMigration,/target_count between 1 and 50000/,"单个全国获客任务必须支持数万真实候选的安全上限");
assert.match(acquisitionScaleMigration,/get_ai_acquisition_discovery_progress[\s\S]*sum\(checkpoint\.result_count\)[\s\S]*grant execute[\s\S]*service_role/,"数千检索分片的进度和原始命中必须在数据库端精确聚合，不能受接口1000行上限截断");
